import random, statistics


def hits(inc, W, k=3):
    h = 0
    for L in inc.values():
        L.sort()
        if any(len({s for (u, s) in L if t <= u <= t + W}) >= k for (t, _) in L):
            h += 1
    return h


def persons(T, W, seed):
    rng = random.Random(seed); inc = {i: [] for i in range(250)}
    for _ in range(T):
        s = rng.randrange(250); r = rng.randrange(249); r = r if r < s else r + 1
        inc[r].append((rng.randrange(7) * 1440 + rng.randint(480, 1320), s))
    return hits(inc, W)


def merchants(n, perday, W, seed):
    rng = random.Random(seed); inc = {i: [] for i in range(n)}
    for m in range(n):
        for d in range(7):
            for _ in range(perday):
                inc[m].append((d * 1440 + rng.randint(480, 1320), rng.randrange(250)))
    return hits(inc, W)


def normal_merch(seed, W):
    rng = random.Random(seed); inc = {i: [] for i in range(25)}
    for m in range(25):
        for _ in range(rng.randint(10, 20)):
            inc[m].append((rng.randrange(7) * 1440 + rng.randint(480, 1320), rng.randrange(250)))
    return hits(inc, W)


for W in (60, 120, 240):
    print("W", W,
          "persons1400", statistics.mean(persons(1400, W, s) for s in range(20)),
          "hf5x30", statistics.mean(merchants(5, 30, W, s) for s in range(20)),
          "normal25", statistics.mean(normal_merch(s, W) for s in range(20)))

