        except ValueError:
            R.err(f"{tag}: time 格式错误 {t['time']}")
            continue
        if not (t_lo <= t["time"] <= t_hi):
            R.err(f"{tag}: time 超出范围 {t['time']}")
        key = (t["time"], int(t["tx_id"][1:]))
        if prev and key < prev:
            R.err(f"{tag}: 未按 (time, tx_id) 升序，或 tx_id 与时间顺序不一致")
        prev = key
        try:
