 def check_tickets(tk_dir: Path, enums, rules, schemas, registry, tx_ids):
     R.start(f"工单 {tk_dir}")
     n = 0
     for p in sorted(tk_dir.glob("*.json")):
         tk = load_json(p)
         for e in schema_errors(schemas, registry, "make_ticket", tk):
