 LEAK = re.compile(r"""(["'/\\]eval["'/\\]|answer(_tx)?\.csv|EVAL_DIR)""")


 def check_leak(dirs):
     R.start("防泄题扫描")
-    allowed = {"evaluate.py", "selfcheck.py", "gen_data.py", "import_amlsim.py"}
